Boolean dei_rf1_rx_hhu_check(void)
{
	UInt32 hhu_sn ; 
    UInt8  i ;

    hhu_sn = ((dei_rf1_vars.rx_data >> 8)&0x00FFFFFF);

	dei_rf1_vars.hhu_sn_used = hhu_sn ; 
            
    for( i = 0 ; i < DEI_RF1_HHU_MAX ; i ++ )
    {
        if( hhu_sn == dei_rf1_hhu.id[i] ) 
        {
            dei_rf1_vars.hhu_sn_used = hhu_sn ; 
			dei_rf1_vars.hhu_id_used = i ;
            
            break ; 
        }
    }

    return !(i == DEI_RF1_HHU_MAX);
}


